package main

import (
	"bufio"
	"fmt"
	"os"
)

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func max(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func lucky(i int) int64 {
	if i == 1 {
		return 0
	}
	d := int64(7)
	if i%2 == 0 {
		d = 4
	}
	return lucky(i/2)*10 + d
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	// aa[k+1] corresponds to aa[k] in the original code, aa[0] stands for aa[-1]
	aa := make([]int64, 2048)
	var l, r int
	var x, y, ans int64

