	aa[1] = 4
	for i := 1; i < 2047; i++ {
		aa[i+1] = lucky(i + 1)
	}
	ans = 0
	for i := 0; i < 2047; i++ {
		x = max(aa[i]+1, int64(l))
		y = min(aa[i+1], int64(r))
		if x <= y {
			ans += (y - x + 1) * aa[i+1]
		}
	}
	fmt.Fprintf(writer, "%d\n", ans)
}
